/* -------------------------------------- Functions -------------------------------------- */

// Function แบ่งข้อมูลเป็นชุดย่อยเพื่อลดขนาด transaction ตอน seed
const chunkArray = <T>(items: T[], size: number): T[][] => {
  const chunks: T[][] = [];

  for (let index = 0; index < items.length; index += size) {
    chunks.push(items.slice(index, index + size));
  }

  return chunks;
};

// Function seed ข้อมูล master_owner_stalls ลง DB
export async function seedMasterOwnerStalls(prisma: PrismaClient): Promise<void> {
  const batches = chunkArray(masterOwnerStallSeedData, 25);

  for (const batch of batches) {
    const operations = batch.map(({ ownerStatus, ...item }) => {
      // master ส่ง Normal = แผงยังใช้งาน แปลงเป็น status ของระบบ
      const status =
        ownerStatus === MASTER_MARKET_ACTIVE_STATUS
          ? MASTER_OWNER_STALL_ACTIVE_STATUS
          : MASTER_OWNER_STALL_INACTIVE_STATUS;

      return prisma.masterOwnerStall.upsert({
        where: {
          marketCode_boothCode_lineUserId: {
            marketCode: item.marketCode,
            boothCode: item.boothCode,
            lineUserId: item.lineUserId as string,
          },
        },
        create: { ...item, status },
        update: {
          boothName: item.boothName,
          cardId: item.cardId,
          firstName: item.firstName,
          lastName: item.lastName,
          status,
        },
      });
    });

    await prisma.$transaction(operations);
  }

  console.info(
    `[seed] master_owner_stalls completed: ${masterOwnerStallSeedData.length} records`,
  );
}
